export interface TankBoundsClips {
  part(tank: Tank, part: TankPart): SwfClip | undefined;
  status(tank: Tank, index: number): SwfClip;
  infection(tank: Tank): SwfClip;
  forcefieldPart(tank: Tank, part: TankPart): SwfClip | undefined;
