  point: Vec,
  symmetric: boolean,
  key: string,
): TankPart[] {
  const y = Math.abs(point.y) <= 3 ? 0 : point.y;
  const twin = symmetric && y !== 0 ? `${key}-twin` : '';
  const part: TankPart = { key, type, radius, x: point.x, y, rotation: 0, scale: 1, twin };
  return twin ? [part, { ...part, key: twin, twin: key, y: -y }] : [part];
