/** Transient state corresponding to TankCreatorScreen.StartDrag/_-5M. */
export interface SelectionDrag {
  parts: TankPart[];
  selection: PartSelection;
  cursor: Vec;
  symmetric: boolean;
  onSide: Map<string, boolean>;
  reference: string | undefined;
  referenceY: number;
  snapOffsetY: number;
  locked: boolean;
