    parts,
    selection,
    cursor,
    symmetric,
    onSide,
    reference: reference?.key,
    referenceY: reference?.y ?? 0,
    snapOffsetY: firstMove.y - (reference?.y ?? 0),
    locked,
    nextTwin: 1,
  };
}

